   101	        quint32 mode = 0;       //!< Combining mode of layer (LayerModeEffects)
   102	        quint32 tattoo;     //!< (unique identifier?)
   103	
   104	        //! As each tile is read from the file, it is buffered here.
   105	        uchar tile[TILE_WIDTH *TILE_HEIGHT *sizeof(QRgb)];
   106	
   107	        //! The data from tile buffer is copied to the Tile by this
   108	        //! method.  Depending on the type of the tile (RGB, Grayscale,
   109	        //! Indexed) and use (image or mask), the bytes in the buffer are
